import{_ as s,h as n,i as e,c as o,v as t,p as E,x as r,m as i,e as m,S as p}from"./chunks/framework.Dvtg8yj2.js";const _=JSON.parse('{"title":"安全数据在 SFT 中的比例","description":"","frontmatter":{"title":"安全数据在 SFT 中的比例","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sft-safety-mix.md","filePath":"llm/sft-safety-mix.md","lastUpdated":1788454257000}'),d={name:"llm/sft-safety-mix.md"};function h(T,a,u,c,S,B){const l=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="安全数据在-sft-中的比例" tabindex="-1">安全数据在 SFT 中的比例 <a class="header-anchor" href="#安全数据在-sft-中的比例" aria-label="Permalink to &quot;安全数据在 SFT 中的比例&quot;">​</a></h1><div class="epigraph"><p>有用与安全在同一条交叉熵里抢词头：安全样本过少，有害配合会被普通示范带过；过多，拒答模板会变成默认助手腔。</p><footer>—— 对照 Ouyang 等 InstructGPT 把政策写入示范与比较，以及 Touvron 等 Llama 2 将有用性与安全性分头建模；比例是配比旋钮，不是公开公式里的常数</footer></div><p>SFT 的普通指令教模型答应用户；安全样本教模型在同一套角色格式下拒绝、改写或给无害替代。二者的题面可以很像——「如何做 X」既可能是无害的 DIY，也可能是危害请求——差别在监督 \\(y\\)。Ouyang 等人的 InstructGPT 从示范阶段就把标注指南里的拒答与边界情况写进 SFT，后续奖励模型与 PPO 再放大；他们没有把安全留给只在 RL 才出现的惩罚。Llama 2-Chat 更明确地把有用性与安全性拆开收集与建模，因为两条目标经常打架。公开的 ShareGPT 与 OpenHermes 混合物通常<strong>安全样本不足或定义不一致</strong>：教师当时的拒绝被当成应当模仿的 \\(y\\)，或反过来把越狱成功的配合也学进去。本篇谈 SFT 里安全数据的功能、如何与有用数据共处、以及为何不存在一个可抄的百分比。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>没有安全监督时，模型对有害题面的行为来自预训练先验与普通指令的类比。预训练里危害步骤可能以教程、小说、论坛形式出现；普通 SFT 又强化「用户要什么就给什么」。结果不是模型「变坏了」，而是从未见过「在 chat 前缀下应当拒绝」这一事件。补安全数据，就是补这类事件的 \\((x_{\\mathrm{unsafe}}, y_{\\mathrm{refuse}})\\)。</p><p>有了安全数据，新问题是比例。交叉熵不理解政策，只理解 token 频率。拒答句式若在测度里太稀，会被大量有用长回答淹没，推理时稍一改写题面就回到配合。若太密，尤其是拒答句式单一（「我无法协助该请求」），模型会把该句式当成助手的无条件开场，无害请求也被拒，即过拒绝（over-refusal）。InstructGPT 用指南定义应当拒绝的类别，而不是靠把安全样本加到占满训练集来「平均出」政策。Llama 2 则承认有用与安全的比较经常相反，因而后面用<strong>分开的奖励模型</strong>，而不是指望 SFT 混合比单独解冲突。</p><h3 id="有用性与安全性在同一交叉熵里打架" tabindex="-1">有用性与安全性在同一交叉熵里打架 <a class="header-anchor" href="#有用性与安全性在同一交叉熵里打架" aria-label="Permalink to &quot;有用性与安全性在同一交叉熵里打架&quot;">​</a></h3><p>同一参数既要降低「请总结这篇文章」的损失，也要降低「请写出可执行的危害步骤」的拒答损失。两个 \\(x\\) 在词法上可能共享「请写出」。梯度在词头上把「请写出」后面的质量推向哪边，取决于两类样本的相对频率、长度（长配合对损失的贡献更大）以及是否多样。安全样本若全是短拒答、有用样本全是长教程，即使条数上安全占 10%，token 上可能只占 1%，有效比例被长度悄悄改写。报告比例必须同时给<strong>样本比与 token 比</strong>。</p><p><span class="marginnote">ShareGPT 里的拒绝是教师政策，不是你的政策。照学会把过时的拒答边界写进学生；照删又会留下越狱成功的配合。清洗时应按自己的政策重写 \\(y\\)，而不是按「助手是否拒绝过」二值保留。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先写政策，再造数据，再谈比例。政策列出：必须拒绝的类别、必须遵守的类别、应澄清的模糊区。SFT 安全样本按类覆盖，而不是只堆「炸弹 / 毒品」几个关键词——否则模型学的是关键词检测，换一种委婉说法就失败。每类里 \\(y\\) 要多样：拒绝、给合法替代、解释边界、在模糊时反问。单一模板等于把安全做成触发器。InstructGPT 的示范阶段与 Llama 2 的安全标注，共同点是<strong>人按指南写或标</strong>，不是从 OpenHermes 里筛含「sorry」的行。</p><p>比例当作扫出来的旋钮，而不是论文常数。公开报告很少给出可复现的「SFT 安全%」。可运行的扫描是：在固定有用数据上，安全样本从很低提到明显可见，看三条曲线——危害请求的配合率、无害敏感题（医疗科普、安全研究、虚构写作）的过拒绝率、以及普通指令的有用性。停在过拒绝尚未陡增、配合率已明显下降的区间。安全样本在 <a href="/llm/instruction-curriculum">课程</a> 的两段都应出现，避免只在末期灌入造成拒答过拟合。有用数据里若已含 ShareGPT 式教师拒绝，应先按政策清洗，再计入安全配额，以免重复计又风格冲突。</p>',12)),(e(),E(p,null,{default:r(()=>[m(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20POL%5B%22%E4%B9%A6%E9%9D%A2%E6%94%BF%E7%AD%96%EF%BC%9A%E6%8B%92%20%2F%20%E5%BA%94%20%2F%20%E6%BE%84%E6%B8%85%22%5D%20--%3E%20GEN%5B%22%E6%8C%89%E7%B1%BB%E6%9E%84%E9%80%A0%E5%AE%89%E5%85%A8%20SFT%22%5D%0A%20%20GEN%20--%3E%20MIX%5B%22%E4%B8%8E%E6%9C%89%E7%94%A8%E6%8C%87%E4%BB%A4%E6%8C%89%E6%A0%B7%E6%9C%AC%E4%B8%8E%20token%20%E9%85%8D%E6%AF%94%22%5D%0A%20%20MIX%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%EF%BC%9A%E9%85%8D%E5%90%88%E7%8E%87%20vs%20%E8%BF%87%E6%8B%92%E7%BB%9D%20vs%20%E6%9C%89%E7%94%A8%E6%80%A7%22%5D%0A%20%20SCAN%20--%3E%20TOOLOW%5B%22%E9%85%8D%E5%90%88%E4%BB%8D%E9%AB%98%EF%BC%9A%E4%B8%8A%E8%B0%83%E6%88%96%E5%A2%9E%E8%A6%86%E7%9B%96%E7%B1%BB%22%5D%0A%20%20SCAN%20--%3E%20TOOHIGH%5B%22%E8%BF%87%E6%8B%92%E7%BB%9D%E9%99%A1%E5%A2%9E%EF%BC%9A%E9%99%8D%E6%9D%83%E6%88%96%E5%A4%9A%E6%A0%B7%E5%8C%96%20y%22%5D%0A%20%20SCAN%20--%3E%20OK%5B%22%E9%80%89%E5%AE%9A%E5%B7%A5%E4%BD%9C%E5%8C%BA%E9%97%B4%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>Llama 2 的启示是：SFT 混合只能把行为推到大概对的区域；有用与安全的细冲突更适合留给比较数据与分开的奖励（见 <a href="/llm/reward-model">奖励模型</a>）。因此 SFT 安全比例的目标应是<strong>不要学坏、学会基本拒绝</strong>，而不是在 SFT 里把政策执行到最终产品精度。把 RLHF 或 DPO 还没做的压力全部加在 SFT 百分比上，会逼出过拒绝。</p><h3 id="负例、正例与对照题" tabindex="-1">负例、正例与对照题 <a class="header-anchor" href="#负例、正例与对照题" aria-label="Permalink to &quot;负例、正例与对照题&quot;">​</a></h3><p>安全桶里应同时有：危害题+拒答（正拒绝）；无害但表面敏感的题+应回答（正有用，防过拒绝）；改写自危害题的合法题（对照）。缺少第二、三类，模型会把「敏感词」当成拒绝特征。这与 InstructGPT 指南里区分恶意与善意请求是同一逻辑。合成安全数据（用模型生成危害题再写拒绝）能扩覆盖，但题面分布像生成器，真实越狱像 ShareGPT 用户。应保留一部分真人措辞的越狱题面，回答按政策重写，而不是用教师原答。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>设有用测度为 \\(p_u\\)，安全测度为 \\(p_s\\)，混合 \\(p=\\lambda p_s+(1-\\lambda)p_u\\)。\\(\\lambda\\) 增大，使拒答 token 的平均对数似然上升，配合性回答在 \\(p\\) 下的质量下降。因为两类 \\(x\\) 重叠，对共享前缀的预测会向在 \\(p\\) 下更常见的延续移动。若 \\(p_s\\) 的 \\(y\\) 熵极低（同一拒绝句），移动会过度，无害 \\(x\\) 也被吸过去。若 \\(p_s\\) 的 \\(y\\) 多样且含澄清，共享前缀后的质量仍然分散，模型必须再读题面细节才能决定，这才是想要的条件行为。</p><p>长度偏置通过损失求和进入机制：一条 2k token 的有害教程若被误留在 \\(p_u\\) 里，其对参数的拉力可能超过十条短拒答。所以清洗（见 <a href="/llm/sft-data-sources">数据来源</a>）是比例的前置条件——脏的长配合会让任何 \\(\\lambda\\) 失效。Token 比 \\(\\lambda_{\\mathrm{tok}}\\) 与样本比 \\(\\lambda_{\\mathrm{n}}\\) 不一致时，真正进入平均损失的是前者。</p><p><span class="marginnote">过拒绝在评测上常表现为安全分虚高、有用分下降。只报安全分会把 \\(\\lambda\\) 调到产品不可用。必须成对看。Llama 2 把两条奖励分开，正是承认单一标量分解决不了这种权衡。</span></p><h3 id="sft-拒绝与-rm-拒绝不是同一层" tabindex="-1">SFT 拒绝与 RM 拒绝不是同一层 <a class="header-anchor" href="#sft-拒绝与-rm-拒绝不是同一层" aria-label="Permalink to &quot;SFT 拒绝与 RM 拒绝不是同一层&quot;">​</a></h3><p>SFT 把具体 \\(y_{\\mathrm{refuse}}\\) 写进条件分布，学的是示范。奖励模型学的是比较：同样题面下，哪一个回答更安全或更有用。SFT 比例不够时，RM 仍可能给拒绝打高分，但策略若从未把拒绝当高概率事件，PPO 或 DPO 要走很远才能到达。SFT 比例过大时，策略已经过拒绝，后面的有用性奖励会与之对拉。因此 \\(\\lambda\\) 的合理区是为后一阶段留出两边都能动的初始化，而不是替代后一阶段。InstructGPT 的三阶段设计（SFT → RM → RL）把这一点写进了流程；只做 SFT 的开源配方更容易把所有压力加在 \\(\\lambda\\) 上。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要从某篇论文里「读出」一个通用百分比。InstructGPT 与 Llama 2 都没有把「SFT 里安全数据占 12%」这类数字写成可迁移定律；他们写的是流程与分头目标。OpenHermes、ShareGPT 的安全含量随下载版本与清洗而变，不能当默认 \\(\\lambda\\)。复制时应自建安全桶，再与公开有用数据混，而不是假设开源指令集已经按你的政策配好。</p><p>政策会变。\\(\\lambda\\) 扫出来的工作点绑定当前 \\(p_s\\) 的句式与类别覆盖。换一套拒绝文案而不重扫，过拒绝曲线会动。安全 SFT 应版本化：政策版本、数据版本、扫描曲线一起存。多语言上，英语拒答模板混进其他语言有用数据，会导致只在英语拒、或在其他语言乱码式拒答，应按语言分层配比。</p><p><span class="marginnote">把全部安全负担放在系统提示里（「你是一个无害的助手」）而 \\(\\lambda=0\\)，等于指望基座理解自然语言政策。SFT 没见过拒绝事件时，系统提示只是又一段条件文本，遵守不稳定。系统提示是推理约束，不是安全数据的替代。</span></p><p>评测集要含故意的过拒绝探针（合法的安全研究、新闻、虚构），否则扫描会单调地提高 \\(\\lambda\\)。危害集也要含改写与多轮（先无害再转入有害），因为 ShareGPT 式真实用户很少一上来就用评测关键词。多轮安全样本的格式必须正确，否则模型只在第一轮拒、第三轮配合。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SFT 安全数据补的是 chat 前缀下的拒绝事件；普通指令不会自动教会拒绝。</li><li>比例 \\(\\lambda\\) 同时改变配合率与过拒绝率，必须报样本比与 token 比，并成对看有用性。</li><li>InstructGPT 从示范阶段写入指南；Llama 2 把有用与安全分头建模，暗示 SFT 混合只能做粗对齐。</li><li>安全 \\(y\\) 要多样，并含表面敏感但应回答的对照题；单一拒答模板会变成触发器。</li><li>公开的 ShareGPT / OpenHermes 不能当政策；教师拒绝要按自己的指南重写。</li><li>\\(\\lambda\\) 用扫描选定，目标是为 RM/DPO 提供两边都能动的初始化，而不是在 SFT 里执行最终政策。</li><li>出处：Ouyang 等，InstructGPT，NeurIPS 2022；Touvron 等，Llama 2，2023。无通用安全百分比可抄，不编造。</li></ul>',16))])}const f=s(d,[["render",h]]);export{_ as __pageData,f as default};
